feet=[.5,1,1.5,2,3,4]

def digest(values):
 h=14695981039346656037
 for v in values:
  for b in struct.pack('<f',v):h=((h^b)*1099511628211)&0xffffffffffffffff
 return h

def wav(path):
 b=path.read_bytes();assert b[:4]==b'RIFF' and b[8:12]==b'WAVE';pos=12;chunks={}
 while pos<len(b):
  kind,n=struct.unpack_from('<4sI',b,pos);pos+=8;chunks[kind]=b[pos:pos+n];pos+=n+(n&1)
 fmt=struct.unpack_from('<HHIIHH',chunks[b'fmt ']);assert fmt==(3,2,48000,384000,8,32)
 x=np.frombuffer(chunks[b'data'],dtype='<f4').reshape(-1,2).astype(np.float64)
 assert x.shape==(192000,2) and np.isfinite(x).all() and np.max(np.abs(x))<1
 return x

def db(x):return 20*math.log10(max(float(x),1e-12))
def rms(x):return math.sqrt(float(np.mean(x*x)))
def segment(x,a,b):return x[round(a*48000):round(b*48000)]
def spectrum(x,a,b,f0):
 y=segment(x,a,b).mean(axis=1);w=np.hanning(len(y));power=np.abs(np.fft.rfft(y*w))**2;freq=np.fft.rfftfreq(len(y),1/48000)
 def band(center):return float(power[np.abs(freq-center)<=max(12,center*.002)].sum())
 harmonics=[band(f0*n) for n in range(1,13)]
 return {'centroid_hz':float(np.dot(freq,power)/max(power.sum(),1e-300)), 'upper_2_to_12_over_fundamental_db':10*math.log10(max(sum(harmonics[1:]),1e-300)/max(harmonics[0],1e-300)), 'fourth_over_fundamental_db':10*math.log10(max(harmonics[3],1e-300)/max(harmonics[0],1e-300)), 'harmonic_energy_fraction':[h/max(sum(harmonics),1e-300) for h in harmonics]}

