summary={'clips':len(records),'seconds':len(records)*4,'finite_samples':len(records)*192000*2,'max_peak_dbfs':max(r['peak_dbfs'] for r in records),'comparisons':comparisons,'isolated_upper_late_vs_onset_db':{r['name']:r['held_2_2_to_2_8_vs_onset_db'] for r in records if r['group']=='upper'},'firm_soft_onset_db':{n:get('firm',n)['onset_rms_dbfs']-get('soft',n)['onset_rms_dbfs'] for n in ['Nylon Pluck','Guitar II','Mandolin','Harp','Kalimba','Vibraphone','Marimba']}}
